		case ra.Name == agent.DefaultAgentName:
			suffix = "    (default)"
		}
		fmt.Fprintf(w, "  %s%s\n", ra.Name, suffix)
	}
	fmt.Fprintln(w)
	if hint != "" {
		fmt.Fprintln(w, hint)
		fmt.Fprintln(w)
	}
	fmt.Fprintln(w, usage)
}

